CREATE TABLE public.faturamento_mensal (mes text PRIMARY KEY CHECK (mes ~ '^\d{4}-\d{2}$'), valor numeric(12,2) NOT NULL, unidade text NOT NULL DEFAULT 'Vila Velha');
GRANT SELECT, INSERT, UPDATE, DELETE ON public.faturamento_mensal TO authenticated;
GRANT ALL ON public.faturamento_mensal TO service_role;
ALTER TABLE public.faturamento_mensal ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner only revenue" ON public.faturamento_mensal FOR ALL TO authenticated USING (public.has_owner_access()) WITH CHECK (public.has_owner_access());
